exec('import csv,os,yfinance as yf\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\nf="virtual_portfolio.csv"; positions=list(csv.DictReader(open(f,encoding="utf-8"))) if os.path.exists(f) else []\nactive=set(x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()); rows=[r for r in csv.DictReader(open("signals_history.csv",encoding="utf-8")) if r["ticker"] in active]; latest={}\nfor r in rows:\n if r["ticker"] not in latest or r["date"]>latest[r["ticker"]]["date"]: latest[r["ticker"]]=r\nrate=float(yf.download("EURUSD=X",period="10d",progress=False,auto_adjust=True)["Close"].dropna().iloc[-1].squeeze()); used={(p["ticker"],p["entry_date"]) for p in positions}; open_tickers={p["ticker"] for p in positions if p["status"]=="OPEN"}\nfor t,r in latest.items():\n if r["signal"]=="ACHAT" and t not in open_tickers and (t,r["date"]) not in used:\n  currency="EUR" if t.endswith((".PA",".AS")) else "USD"; price=float(r["price"]); quantity=1000/price if currency=="EUR" else 1000*rate/price; positions.append({"ticker":t,"entry_date":r["date"],"entry_price":round(price,4),"currency":currency,"eurusd_entry":round(rate,6) if currency=="USD" else 1,"quantity":round(quantity,6),"invested_eur":1000,"target_price":round(price*1.03,4),"stop_price":round(price*0.98,4),"status":"OPEN","last_price":round(price,4),"current_value_eur":1000,"pnl_eur":0,"pnl_pct":0,"exit_date":"","exit_price":"","exit_reason":""}); print("ACHAT VIRTUEL :",t,"| 1000 EUR | Objectif +3% | Stop -2%")\nfor p in positions:\n if p["status"]!="OPEN": continue\n t=p["ticker"]; tz="Europe/Paris" if t.endswith((".PA",".AS")) else "America/New_York"; today=datetime.now(ZoneInfo(tz)).date(); d=yf.download(t,period="3mo",progress=False,auto_adjust=True); d=d[[x.date()<today for x in d.index]]; after=d[d.index.strftime("%Y-%m-%d")>p["entry_date"]]; exit_found=False\n for day,row in after.iterrows():\n  if float(row["Low"].iloc[0] if hasattr(row["Low"],"iloc") else row["Low"])<=float(p["stop_price"]): p["status"]="CLOSED"; p["exit_date"]=day.strftime("%Y-%m-%d"); p["exit_price"]=p["stop_price"]; p["exit_reason"]="STOP -2%"; exit_found=True; break\n  if float(row["High"].iloc[0] if hasattr(row["High"],"iloc") else row["High"])>=float(p["target_price"]): p["status"]="CLOSED"; p["exit_date"]=day.strftime("%Y-%m-%d"); p["exit_price"]=p["target_price"]; p["exit_reason"]="OBJECTIF +3%"; exit_found=True; break\n current=float(p["exit_price"]) if exit_found else float(d["Close"].dropna().iloc[-1].squeeze()); p["last_price"]=round(current,4); value=float(p["quantity"])*current if p["currency"]=="EUR" else float(p["quantity"])*current/rate; p["current_value_eur"]=round(value,2); p["pnl_eur"]=round(value-float(p["invested_eur"]),2); p["pnl_pct"]=round((value/float(p["invested_eur"])-1)*100,2); print(p["ticker"],"|",p["status"],"| Valeur",p["current_value_eur"],"EUR | Resultat",p["pnl_eur"],"EUR |",p["pnl_pct"],"%",("| "+p["exit_reason"] if exit_found else ""))\nwith open(f,"w",newline="",encoding="utf-8") as q:\n fields=["ticker","entry_date","entry_price","currency","eurusd_entry","quantity","invested_eur","target_price","stop_price","status","last_price","current_value_eur","pnl_eur","pnl_pct","exit_date","exit_price","exit_reason"]; w=csv.DictWriter(q,fieldnames=fields,extrasaction="ignore"); w.writeheader(); w.writerows(positions)\nprint("Suivi et protections du portefeuille mis a jour :",,f)')
